/**
 * Look up the [normal, skill, burst] skill IDs for an Enka avatar.
 * Traveler entries are depot-specific, so the depot key is tried first;
 * every other character falls through to the plain avatarId key.
 */
export function getEnkaSkillOrder(avatarId: number, skillDepotId?: number): EnkaSkillOrder | undefined {
  if (skillDepotId !== undefined) {
    const depotEntry = ENKA_SKILL_ORDER[`${avatarId}-${skillDepotId}`];
    if (depotEntry) return depotEntry;
  }
  return ENKA_SKILL_ORDER[String(avatarId)];
}
